-- Preserved from the legacy purchasing endpoint.
WITH ledger AS(SELECT ge.id,ge.bill_line_id,bl.bill_id,b.supplier_id,b.supplier_invoice,ge.gst_basis,ge.tax_code_id,ge.tax_rate,ge.net,ge.tax,ge.recoverable_tax,ge.input_account_id,ge.debit_account_id,ge.attribution_date,
CASE WHEN ge.gst_basis='CASH' THEN coalesce(a.in_period,0) ELSE CASE WHEN ge.attribution_date IS NOT NULL AND (CAST(:from AS date) IS NULL OR ge.attribution_date>=CAST(:from AS date)) AND (CAST(:to AS date) IS NULL OR ge.attribution_date<=CAST(:to AS date)) THEN ge.recoverable_tax ELSE 0 END+coalesce(a.in_period,0) END AS attributed_tax,
CASE WHEN ge.gst_basis='CASH' THEN greatest(0,bl.remaining_tax-coalesce(a.total,0)) ELSE 0 END AS pending_payment_tax,CASE WHEN ge.gst_basis='CASH' THEN greatest(0,coalesce(a.total,0)-bl.remaining_tax) ELSE 0 END AS pending_refund_tax
FROM accounting.purchase_gst_entries ge JOIN purchase.bill_line_balances bl ON bl.company_id=ge.company_id AND bl.id=ge.bill_line_id JOIN purchase.bills b ON b.company_id=bl.company_id AND b.id=bl.bill_id
LEFT JOIN LATERAL(SELECT sum(ga.gst_amount) AS total,sum(ga.gst_amount) FILTER(WHERE (CAST(:from AS date) IS NULL OR ga.attribution_date>=CAST(:from AS date)) AND (CAST(:to AS date) IS NULL OR ga.attribution_date<=CAST(:to AS date))) AS in_period FROM(SELECT gst_amount,attribution_date FROM accounting.purchase_gst_attributions WHERE company_id=ge.company_id AND bill_line_id=ge.bill_line_id UNION ALL SELECT gst_amount,adjustment_date FROM accounting.purchase_gst_adjustments WHERE company_id=ge.company_id AND bill_line_id=ge.bill_line_id AND gst_basis=ge.gst_basis)ga)a ON true
WHERE ge.company_id=:company AND (CAST(:supplier AS uuid) IS NULL OR b.supplier_id=CAST(:supplier AS uuid)))
